"""Every rounding rule of meterbill lives here."""

from __future__ import annotations

import math
from decimal import ROUND_DOWN, ROUND_HALF_EVEN, ROUND_HALF_UP, Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)
_DECIMAL_MODES = {HALF_UP: ROUND_HALF_UP, HALF_EVEN: ROUND_HALF_EVEN, DOWN: ROUND_DOWN}


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or not step > 0:
        raise ValueError("step must be positive")


def _units(fraction: Fraction, method: str) -> int:
    """`fraction` (>= 0) rounded to a whole number by `method`."""
    whole, rest = divmod(fraction.numerator, fraction.denominator)
    twice = 2 * rest
    if method == HALF_UP:
        up = twice >= fraction.denominator
    elif method == HALF_EVEN:
        up = twice > fraction.denominator or (twice == fraction.denominator and whole % 2 == 1)
    else:
        up = False
    return whole + 1 if up else whole


def _build(units: int, negative: bool, step: Decimal) -> Decimal:
    """`units` steps as a Decimal with the exponent of `step`, exactly."""
    t = step.as_tuple()
    coefficient = int("".join(map(str, t.digits))) * units
    digits = tuple(int(c) for c in str(coefficient))
    return Decimal((1 if negative else 0, digits, t.exponent))


def _round_units(value: Decimal, step: Decimal, method: str) -> int:
    return _units(abs(Fraction(value)) / Fraction(step), method)


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    if not value.is_finite():
        return value.quantize(step, rounding=_DECIMAL_MODES[method])
    units = _round_units(value, step, method)
    return _build(units, value.is_signed(), step)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    amounts = list(amounts)
    _check(Decimal(0), step, HALF_UP)
    if not all(isinstance(a, Decimal) for a in amounts):
        raise TypeError("amounts must be Decimal")
    if not amounts:
        return []
    # parts: signed units; negative zero kept as the sign flag
    units = [_round_units(a, step, DOWN) for a in amounts]
    negs = [a.is_signed() for a in amounts]
    signed = [-u if n else u for u, n in zip(units, negs)]
    exact_sum = sum((Fraction(a) for a in amounts), Fraction(0))
    whole_units = _units(abs(exact_sum) / Fraction(step), HALF_UP)
    whole_neg = exact_sum < 0
    whole = -whole_units if whole_neg else whole_units
    parts_sum = sum(signed)
    rest = whole - parts_sum
    # sign of a zero rest: negative only when both whole and the parts' sum are zero and whole is negative
    rest_neg = rest < 0 or (rest == 0 and whole_neg and whole_units == 0 and parts_sum == 0)
    out = [_build(u, n, step) for u, n in zip(units, negs)]
    for i in range(len(amounts) - 1, -1, -1):
        if amounts[i] != 0:
            total = signed[i] + rest
            if total == 0:
                neg = negs[i] and signed[i] == 0 and rest_neg and rest == 0
            else:
                neg = total < 0
            out[i] = _build(abs(total), neg, step)
            break
    return out


def legacy_cents(value: float, places: int = 2) -> float:
    if not isinstance(places, int) or isinstance(places, bool) or not 0 <= places <= 6:
        raise ValueError("places must be an integer from 0 to 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not isinstance(places, int) or isinstance(places, bool) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, Decimal):
        if not value.is_finite():
            return format(value, "f")
        rounded = round_amount(value, Decimal(1).scaleb(-places), method)
        return format(rounded, "f")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    raise TypeError("value must be a float or a Decimal")
